int create_graphics_buffer_surface(struct drm_device *dev, void *data,
                                   struct drm_file *file_priv) {
    int ret = -EINVAL;
    struct drm_surface_create_args *args = data;
    struct graphics_surface *surface = NULL;

    if (!dev || !args || !file_priv)
        return ret;

    surface = kzalloc(sizeof(*surface), GFP_KERNEL);
    if (!surface)
        return -ENOMEM;

    mutex_lock(&dev->mode_config.mutex);

    ret = allocate_and_map_buffer(dev, args, &surface->buffer);
    if (ret) {
        goto error_cleanup;
    }

    ret = init_surface_resources(surface, args, file_priv);
    if (ret) {
        goto error_cleanup;
    }

    surface->refcount = 1;
    surface->dev = dev;
    surface->file_priv = file_priv;

    args->handle = add_surface_to_global_list(surface);

    mutex_unlock(&dev->mode_config.mutex);

    return 0;

error_cleanup:
    release_surface_resources(surface);
    kfree(surface);
    mutex_unlock(&dev->mode_config.mutex);
    return ret;
}

int create_graphics_buffer_surface(struct drm_device *dev, void *data,
                                   struct drm_file *file_priv) {
    struct drm_mode_create_dumb *args = data;
    struct drm_gem_object *obj;
    struct drm_plane *plane;
    struct drm_framebuffer *fb;
    int ret;

    if (!args || !dev || !file_priv)
        return -EINVAL;

    if (args->width == 0 || args->height == 0 || args->bpp == 0)
        return -EINVAL;

    obj = drm_gem_object_create(dev, args->width * args->height * args->bpp / 8);
    if (IS_ERR(obj))
        return PTR_ERR(obj);

    fb = drm_framebuffer_alloc(dev, args->width, args->height, args->bpp, 0, obj);
    if (IS_ERR(fb)) {
        drm_gem_object_put(obj);
        return PTR_ERR(fb);
    }

    plane = drm_plane_find(dev, DRM_PLANE_TYPE_OVERLAY);
    if (!plane) {
        drm_framebuffer_put(fb);
        drm_gem_object_put(obj);
        return -ENODEV;
    }

    ret = drm_mode_attach_plane(dev, fb, plane);
    if (ret) {
        drm_framebuffer_put(fb);
        drm_gem_object_put(obj);
        return ret;
    }

    args->handle = obj->handle;
    args->pitch = obj->size / args->height;
    args->offset = 0;

    return 0;
}

int create_graphics_buffer_surface(struct drm_device *dev, void *data, struct drm_file *file_priv) {
    struct drm_mode_create_dumb args;
    struct drm_gem_object *obj;
    int ret;

    if (!dev || !data || !file_priv)
        return -EINVAL;

    memcpy(&args, data, sizeof(args));

    obj = drm_gem_object_create(dev, args.size);
    if (IS_ERR(obj))
        return PTR_ERR(obj);

    /* Initialize user surface with obj and args */
    ret = drm_mode_attach_mode(dev, args.width, args.height, obj);
    if (ret)
        goto error_free_gem;

    return 0;

error_free_gem:
    drm_gem_object_put(obj);
    return ret;
}

int create_graphics_buffer_surface(struct drm_device *dev, void *data, struct drm_file *file_priv) {
    struct my_surface *surface;
    int ret = 0;

    if (!dev || !data || !file_priv) {
        return -EINVAL;
    }

    surface = kzalloc(sizeof(*surface), GFP_KERNEL);
    if (!surface) {
        return -ENOMEM;
    }

    mutex_lock(&dev->mode_config.mutex);
    ret = allocate_and_init_surface(dev, data, surface, file_priv);
    if (ret < 0) {
        kfree(surface);
        mutex_unlock(&dev->mode_config.mutex);
        return ret;
    }

    ret = manage_surface_resources(dev, surface, file_priv);
    if (ret < 0) {
        cleanup_surface(surface);
        kfree(surface);
        mutex_unlock(&dev->mode_config.mutex);
        return ret;
    }

    prepare_surface_response(surface, data);
    mutex_unlock(&dev->mode_config.mutex);

    return 0;
}

int create_guest_graphics_surface(struct drm_device *dev, void *data, struct drm_file *file_priv) {
    struct drm_mode_create_guest_graphics_surface *args = data;
    struct guest_graphics_surface *surface;
    int ret = -EINVAL;

    if (!args)
        return ret;

    surface = kzalloc(sizeof(*surface), GFP_KERNEL);
    if (!surface)
        return -ENOMEM;

    mutex_init(&surface->lock);

    ret = guest_graphics_buffer_init(dev, surface, args->width, args->height, args->format);
    if (ret)
        goto err_free_surface;

    ret = drm_gem_object_init(dev, &surface->gem, args->size);
    if (ret)
        goto err_cleanup_buffer;

    surface->handle = drm_gem_handle_create(file_priv, &surface->gem);
    if (!surface->handle) {
        ret = -ENOENT;
        goto err_cleanup_gem;
    }

    args->handle = surface->handle;

    return 0;

err_cleanup_gem:
    drm_gem_object_put(&surface->gem);
err_cleanup_buffer:
    guest_graphics_buffer_cleanup(surface);
err_free_surface:
    mutex_destroy(&surface->lock);
    kfree(surface);
    return ret;
}
